"use client";
/* Wizard, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Wizard(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("wizard"); }, []);
  return React.createElement("piix-sprite", { "name": "wizard", ...piixAttrs(props) });
}

export default Wizard;
